"""Refresh selected pre-export stills with the renderer's exact timeline and compositor."""
from pathlib import Path
import datetime,hashlib,json,sys,yaml
from PIL import Image
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT/'studio/tools'));import render
sid=sys.argv[1];indices=[int(x) for x in sys.argv[2:]];ep=ROOT/'studio/episodes'/sid;folder=ROOT/'studio/media'/sid/'render'
assert sid=='hb-c11-trafik'
assert not (ep/'render.json').exists(),'Do not mutate reviewed exported stills with this helper.'
s=yaml.safe_load((ep/'script.yaml').read_text());render.configure_style(s);rows={r['sentence_id']:r for r in s['sentences']};timeline,frames=render.build_timeline(s);assert timeline==json.loads((folder/'timeline.json').read_text()),'Timing changed; use full still rendering.'
paths={s['render']['background_image']}|{rows[timeline[i]['sentence_id']]['render_image'] for i in indices if timeline[i]['kind']=='sentence'};images={p:Image.open(ROOT/p).convert('RGB') for p in paths};style=s['render']['background_style'];back=render.prepare_background(images[s['render']['background_image']],style);evidence=[]
for i in indices:
 item=timeline[i]
 for j,chunk in enumerate(item.get('display_segments') or [item]):
  shown={**item,**chunk}
  if item.get('display_segments'):shown['segment_index']=j
  card,_=render.make_card(s,shown,rows,images);still=render.composite_rgb_frame(back,(shown['start_frame']+shown['frames']/2)/(frames-1),style,card.convert('RGB'),card.getchannel('A'));dest=folder/f'frame-{i:02d}.png'
  if j==0:still.save(dest)
  if item.get('display_segments'):dest=folder/f'frame-{i:02d}-segment-{j:02d}.png';still.save(dest)
  evidence.append({'frame':i,'segment':j,'path':str(dest.relative_to(ROOT)),'sha256':hashlib.sha256(dest.read_bytes()).hexdigest()})
(ep/'partial-still-refresh.json').write_text(json.dumps({'created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'script_sha256':hashlib.sha256((ep/'script.yaml').read_bytes()).hexdigest(),'scope':'Selected stills regenerated by the current renderer functions at unchanged actual timeline positions. No encoder or audio mixing.','frames':evidence},indent=2)+'\n');print(sid,len(evidence),'exact timeline stills refreshed')
